<script setup>
import {ref} from 'vue';import {Head,useForm} from '@inertiajs/vue3';
import AppLayout from '../Layouts/AppLayout.vue';import AppModal from '../Components/AppModal.vue';import ConfirmAction from '../Components/ConfirmAction.vue';import FormErrors from '../Components/FormErrors.vue';
defineProps({subjects:Array});const open=ref(false),editing=ref(null),action=ref(null);const form=useForm({code:'',name:'',department:'',is_active:true});
function show(subject=null){editing.value=subject;form.clearErrors();Object.assign(form,subject?{code:subject.code,name:subject.name,department:subject.department||'',is_active:subject.is_active}:{code:'',name:'',department:'',is_active:true});open.value=true;}
function save(){form.submit(editing.value?'put':'post','/manage/course/subjects'+(editing.value?'/'+editing.value.id:''),{onSuccess:()=>open.value=false});}
</script>
<template><Head title="Danh mục môn học"/><AppLayout><div class="page-heading"><div><h1>Danh mục môn học</h1><p>Tổ chức ngân hàng câu hỏi và đề thi kết thúc môn.</p></div><button @click="show()">+ Thêm môn học</button></div><div class="card"><div class="tablewrap"><table><thead><tr><th>Mã môn</th><th>Tên môn</th><th>Khoa / đơn vị</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody><tr v-for="subject in subjects" :key="subject.id"><td>{{subject.code}}</td><td>{{subject.name}}</td><td>{{subject.department||'—'}}</td><td><span class="pill">{{subject.is_active?'Đang sử dụng':'Ngừng sử dụng'}}</span></td><td><div class="actions"><button class="secondary" @click="show(subject)">Sửa</button><button class="secondary" @click="action={url:'/manage/course/subjects/'+subject.id,title:'Xóa môn học',message:'Xóa môn '+subject.name+'? Môn đã có học liệu sẽ được giữ lại.'}">Xóa</button></div></td></tr><tr v-if="!subjects.length"><td colspan="5" class="empty-state">Chưa có môn học. Thêm môn đầu tiên để xây dựng học liệu.</td></tr></tbody></table></div></div><AppModal :open="open" :title="editing?'Sửa môn học':'Thêm môn học'" :busy="form.processing" @close="open=false"><form @submit.prevent="save"><FormErrors :errors="form.errors"/><div class="field"><label for="subject-code">Mã môn</label><input id="subject-code" v-model="form.code" required maxlength="50"/></div><div class="field"><label for="subject-name">Tên môn</label><input id="subject-name" v-model="form.name" required maxlength="255"/></div><div class="field"><label for="subject-dept">Khoa / đơn vị</label><input id="subject-dept" v-model="form.department" maxlength="255"/></div><div class="field"><label for="subject-active">Trạng thái</label><select id="subject-active" v-model="form.is_active"><option :value="true">Đang sử dụng</option><option :value="false">Ngừng sử dụng</option></select></div><div class="modal-actions"><button type="button" class="secondary" @click="open=false">Hủy</button><button :disabled="form.processing">Lưu môn học</button></div></form></AppModal><ConfirmAction :action="action" @close="action=null"/></AppLayout></template>
